description:
创建 Playwright 测试用例验证 admin-app 功能

测试文件 admin-app/tests/admin.spec.js：
```js
import { test, expect } from '@playwright/test'

test.describe('admin-app', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:5173')
  })

  test('节点列表页显示所有节点', async ({ page }) => {
    await expect(page.locator('h1')).toContainText('节点列表')
    // 等待节点加载
    await page.waitForSelector('[class*="grid"] > div')
    const cards = await page.locator('[class*="cursor-pointer"]').count()
    expect(cards).toBeGreaterThan(40)
  })

  test('点击节点卡片跳转到编辑器', async ({ page }) => {
    // 点击第一个节点
    await page.locator('[class*="cursor-pointer"]').first().click()
    // 验证跳转到编辑器页面
    await expect(page).toHaveURL(/\/editor\//)
    await expect(page.locator('text=data.json')).toBeVisible()
  })

  test('编辑器 tab 切换正常', async ({ page }) => {
    await page.goto('http://localhost:5173/editor/opc-fit-test')
    // 默认显示 data.json
    await expect(page.locator('text=data.json')).toBeVisible()
    // 点击 index.md tab
    await page.click('text=index.md')
    await expect(page.locator('text=INDEX.MD')).toBeVisible()
  })

  test('节点选择器正常工作', async ({ page }) => {
    await page.goto('http://localhost:5173/editor/opc-fit-test')
    // 点击节点选择器
    await page.click('button:has-text("选择节点"), button:has-text("OPC")')
    // 验证下拉列表出现
    await expect(page.locator('text=选择节点').or(page.locator('text=OPC'))).toBeVisible()
  })

  test('data.json 表单编辑和保存', async ({ page }) => {
    await page.goto('http://localhost:5173/editor/opc-fit-test')
    // 找到标题输入框
    const titleInput = page.locator('input').filter({ hasText: '' }).first()
    // 编辑并保存
    await page.click('button:has-text("保存")')
    // 验证保存成功提示（短暂显示）
  })

  test('index.md Markdown 编辑器加载', async ({ page }) => {
    await page.goto('http://localhost:5173/editor/opc-fit-test')
    await page.click('text=index.md')
    // 验证 Markdown 编辑器加载
    await expect(page.locator('.w-md-editor')).toBeVisible()
  })
})
```

Playwright 配置（playwright.config.js）：
```js
import { defineConfig } from '@playwright/test'

export default defineConfig({
  testDir: './tests',
  timeout: 30000,
  use: {
    baseURL: 'http://localhost:5173',
    headless: true,
  },
  webServer: {
    command: 'npm run dev',
    port: 5173,
    reuseExistingServer: true,
  },
})
```
